from jsonb_to_recordset($q$[{"id":6839,"materia":"ling","nivel":2,"enunciado":"Em \"A cidade acordou cedo e espreguiçou suas avenidas\", a figura de linguagem é a:","opcoes":["Personificação (prosopopeia)","Hipérbole (exagero)","Metonímia (troca de nomes)","Antítese"],"explicacao":"Atribuem-se ações humanas à cidade."},{"id":6840,"materia":"ling","nivel":2,"enunciado":"Num anúncio com \"Compre já! Corra para a loja!\", predomina a função da linguagem:","opcoes":["Conativa (apelativa)","Referencial (informativa)","Poética","Fática"],"explicacao":"O foco é convencer o receptor."},{"id":6841,"materia":"ling","nivel":3,"enunciado":"Um verbete de dicionário que explica o que é \"verbo\" usa, sobretudo, a função:","opcoes":["Metalinguística","Emotiva (expressiva)","Conativa (apelativa)","Fática"],"explicacao":"É a língua falando da própria língua."},{"id":6842,"materia":"ling","nivel":3,"enunciado":"O uso de \"nós vai\" na fala de um grupo com pouco acesso à escola é exemplo de variação:","opcoes":["Social (diastrática)","Histórica (diacrônica)","Situacional (diafásica)","Nenhuma, pois é erro sem explicação"],"explicacao":"A variação ligada a grupos sociais é diastrática."},{"id":6843,"materia":"ling","nivel":3,"enunciado":"A primeira fase do Modernismo brasileiro (a partir de 1922) se caracteriza por:","opcoes":["Verso livre, humor e ruptura com o academicismo","Rigor métrico e culto à forma perfeita","Idealização do índio como herói medieval","Sentimentalismo e fuga para a morte"],"explicacao":"O rigor formal é marca do Parnasianismo."},{"id":6844,"materia":"ling","nivel":3,"enunciado":"\"Vidas Secas\", de Graciliano Ramos, pertence ao:","opcoes":["Romance de 30, de denúncia social","Romantismo indianista do século XIX","Arcadismo mineiro do século XVIII","Parnasianismo"],"explicacao":"Retrata a família de retirantes no sertão."},{"id":6845,"materia":"ling","nivel":4,"enunciado":"\"Memórias Póstumas de Brás Cubas\" (1881) é considerado o marco inicial do:","opcoes":["Realismo no Brasil","Romantismo no Brasil","Modernismo no Brasil","Simbolismo no Brasil"],"explicacao":"O narrador defunto ironiza a sociedade da época."},{"id":6846,"materia":"ling","nivel":3,"enunciado":"A \"Canção do Exílio\", de Gonçalves Dias, é típica do:","opcoes":["Romantismo, com nacionalismo e saudade da pátria","Barroco, com conflitos religiosos e morais","Realismo, com crítica à sociedade burguesa","Modernismo, com humor"],"explicacao":"\"Minha terra tem palmeiras onde canta o sabiá.\""},{"id":6847,"materia":"ling","nivel":3,"enunciado":"Um texto que imita outro com intenção crítica ou humorística, invertendo seu sentido, é uma:","opcoes":["Paródia","Paráfrase","Citação","Epígrafe"],"explicacao":"A paráfrase mantém o sentido original."},{"id":6848,"materia":"ling","nivel":4,"enunciado":"A charge se diferencia do cartum porque:","opcoes":["Critica um fato ou personagem da atualidade","Não usa imagens, só palavras escritas","É sempre um texto longo e argumentativo","Trata só de temas atemporais"],"explicacao":"O cartum aborda temas universais, sem data."},{"id":6849,"materia":"ling","nivel":3,"enunciado":"Em inglês, a palavra \"However\" introduz uma ideia de:","opcoes":["Contraste","Adição","Conclusão","Exemplo"],"explicacao":"Equivale a \"no entanto\"."},{"id":6850,"materia":"ling","nivel":4,"enunciado":"A poesia concreta (anos 1950) se caracteriza por:","opcoes":["Explorar o espaço visual da palavra na página","Usar apenas sonetos com rimas ricas","Contar histórias longas em prosa poética","Imitar os trovadores"],"explicacao":"Forma e sentido se integram visualmente."},{"id":6851,"materia":"mat","nivel":2,"enunciado":"Num mapa de escala 1:50.000, 4 cm representam:","opcoes":["2 km","20 km","200 m","50 km"],"explicacao":"4 × 50.000 = 200.000 cm = 2 km."},{"id":6852,"materia":"mat","nivel":3,"enunciado":"Lançando dois dados, a probabilidade de a soma dar 10 é:","opcoes":["1/12","1/6","1/36","5/36"],"explicacao":"(4,6), (5,5) e (6,4): 3 casos em 36."},{"id":6853,"materia":"mat","nivel":2,"enunciado":"Um táxi cobra R$ 5,00 de bandeirada e R$ 2,50 por km. Uma corrida de 12 km custa:","opcoes":["R$ 35,00","R$ 30,00","R$ 32,50","R$ 60,00"],"explicacao":"5 + 2,5 × 12 = 35."},{"id":6854,"materia":"mat","nivel":2,"enunciado":"A área de um círculo de 10 m de raio, com π = 3,14, é:","opcoes":["314 m²","31,4 m²","62,8 m²","100 m²"],"explicacao":"A = π r² = 3,14 × 100."},{"id":6855,"materia":"mat","nivel":3,"enunciado":"Uma caixa d'água cilíndrica tem raio de 2 m e altura de 5 m. Com π = 3, seu volume é:","opcoes":["60 m³","30 m³","20 m³","120 m³"],"explicacao":"V = π r² h = 3 × 4 × 5."},{"id":6856,"materia":"mat","nivel":3,"enunciado":"A mediana de 3, 7, 8, 12, 15 e 20 é:","opcoes":["10","8","12","9"],"explicacao":"Com quantidade par, faz-se a média dos centrais: (8 + 12) ÷ 2."},{"id":6857,"materia":"mat","nivel":4,"enunciado":"Um produto aumenta 25% e depois tem desconto de 20%. Em relação ao preço inicial, ele fica:","opcoes":["Igual","5% mais caro","5% mais barato","10% mais caro"],"explicacao":"1,25 × 0,8 = 1."},{"id":6858,"materia":"mat","nivel":4,"enunciado":"Na escala Richter, cada ponto equivale a 10 vezes mais amplitude. Um tremor de magnitude 7 tem, em relação a um de 5, amplitude:","opcoes":["100 vezes maior","2 vezes maior","20 vezes maior","1.000 vezes maior"],"explicacao":"10² = 100."},{"id":6859,"materia":"mat","nivel":3,"enunciado":"Numa reunião com 10 pessoas, cada uma aperta a mão de todas as outras uma vez. São ao todo:","opcoes":["45 apertos","90 apertos","100 apertos","20 apertos"],"explicacao":"C(10,2) = 10 × 9 ÷ 2."},{"id":6860,"materia":"mat","nivel":3,"enunciado":"No mesmo instante, um poste projeta sombra de 6 m e uma pessoa de 1,8 m projeta sombra de 1,2 m. A altura do poste é:","opcoes":["9 m","7,2 m","4 m","10,8 m"],"explicacao":"Semelhança: 1,8/1,2 = h/6."},{"id":6861,"materia":"mat","nivel":2,"enunciado":"Um carro faz 12 km/L e a gasolina custa R$ 6,00. Uma viagem de 360 km gasta, em combustível:","opcoes":["R$ 180","R$ 72","R$ 216","R$ 360"],"explicacao":"360 ÷ 12 = 30 L; 30 × 6."},{"id":6862,"materia":"mat","nivel":4,"enunciado":"Quantas senhas de 3 letras distintas podem ser formadas com as 26 letras do alfabeto?","opcoes":["15.600","17.576","2.600","78"],"explicacao":"26 × 25 × 24."},{"id":6863,"materia":"fis","nivel":2,"enunciado":"72 km/h correspondem a:","opcoes":["20 m/s","72 m/s","7,2 m/s","259 m/s"],"explicacao":"Divide-se por 3,6."},{"id":6864,"materia":"fis","nivel":2,"enunciado":"Uma força de 10 N age sobre um corpo de 2 kg. Sua aceleração é:","opcoes":["5 m/s²","20 m/s²","12 m/s²","0,2 m/s²"],"explicacao":"F = m · a."},{"id":6865,"materia":"fis","nivel":3,"enunciado":"A energia cinética de um corpo de 4 kg a 3 m/s é:","opcoes":["18 J","12 J","36 J","6 J"],"explicacao":"Ec = m · v² ÷ 2 = 4 × 9 ÷ 2."},{"id":6866,"materia":"fis","nivel":3,"enunciado":"Dois resistores de 4 Ω e 6 Ω em série são ligados a 20 V. A corrente é:","opcoes":["2 A","5 A","10 A","0,5 A"],"explicacao":"Req = 10 Ω; i = U/R."},{"id":6867,"materia":"fis","nivel":3,"enunciado":"Dois resistores de 6 Ω ligados em paralelo equivalem a:","opcoes":["3 Ω","12 Ω","6 Ω","36 Ω"],"explicacao":"Resistores iguais em paralelo: R dividido pelo número deles."},{"id":6868,"materia":"fis","nivel":3,"enunciado":"Uma onda tem frequência de 50 Hz e comprimento de 2 m. Sua velocidade é:","opcoes":["100 m/s","25 m/s","52 m/s","0,04 m/s"],"explicacao":"v = λ · f."},{"id":6869,"materia":"fis","nivel":3,"enunciado":"Ao passar do ar para a água, a luz:","opcoes":["Muda de velocidade e pode mudar de direção","Para de se propagar na água","Fica mais rápida do que no ar","Muda de frequência"],"explicacao":"É a refração."},{"id":6870,"materia":"fis","nivel":4,"enunciado":"Um transformador tem 1.000 espiras no primário, ligado a 220 V, e 50 espiras no secundário. A tensão de saída é:","opcoes":["11 V","4.400 V","110 V","22 V"],"explicacao":"U₁/U₂ = N₁/N₂."},{"id":6871,"materia":"qui","nivel":2,"enunciado":"Água e óleo formam uma mistura:","opcoes":["Heterogênea, separável por funil de decantação","Homogênea, separável por filtração","Homogênea, separável por destilação simples","Heterogênea, inseparável"],"explicacao":"São imiscíveis e têm densidades diferentes."},{"id":6872,"materia":"qui","nivel":3,"enunciado":"A destilação fracionada é usada para separar:","opcoes":["Líquidos miscíveis com pontos de ebulição diferentes","Sólidos de tamanhos diferentes por peneiração","Areia e água por simples decantação","Gases de sólidos"],"explicacao":"É o processo do refino do petróleo."},{"id":6873,"materia":"qui","nivel":3,"enunciado":"Dissolvem-se 20 g de sal em água até 500 mL de solução. A concentração é:","opcoes":["40 g/L","10 g/L","4 g/L","100 g/L"],"explicacao":"20 g ÷ 0,5 L."},{"id":6874,"materia":"qui","nivel":3,"enunciado":"A massa de 2 mol de água (M = 18 g/mol) é:","opcoes":["36 g","18 g","9 g","72 g"],"explicacao":"2 × 18."},{"id":6875,"materia":"qui","nivel":3,"enunciado":"O catalisador acelera uma reação porque:","opcoes":["Diminui a energia de ativação, sem ser consumido","Aumenta a temperatura do sistema reacional","É consumido no lugar dos reagentes","Aumenta a energia de ativação"],"explicacao":"Ele oferece um caminho alternativo."},{"id":6876,"materia":"qui","nivel":4,"enunciado":"Num equilíbrio entre gases, aumentar a pressão desloca o equilíbrio para o lado com:","opcoes":["Menor número de mols gasosos","Maior número de mols gasosos","Mais sólidos","Mais calor"],"explicacao":"Princípio de Le Chatelier."},{"id":6877,"materia":"qui","nivel":4,"enunciado":"Um material radioativo tem meia-vida de 5 anos. De 80 g, depois de 15 anos restam:","opcoes":["10 g","20 g","40 g","5 g"],"explicacao":"80 → 40 → 20 → 10."},{"id":6878,"materia":"qui","nivel":4,"enunciado":"Numa pilha, o ânodo é o eletrodo onde ocorre:","opcoes":["Oxidação","Redução","Neutralização","Fusão"],"explicacao":"No cátodo ocorre a redução."},{"id":6879,"materia":"qui","nivel":2,"enunciado":"A combustão completa do metano (CH₄) produz:","opcoes":["Gás carbônico e água","Monóxido de carbono e fuligem","Oxigênio e hidrogênio","Metanol"],"explicacao":"CH₄ + 2 O₂ → CO₂ + 2 H₂O."},{"id":6880,"materia":"bio","nivel":3,"enunciado":"A eutrofização de um lago ocorre quando:","opcoes":["Excesso de nutrientes faz algas proliferarem e falta O₂","A água fica limpa demais e sem nenhum nutriente","Os peixes se multiplicam sem nenhum controle","O lago congela"],"explicacao":"Comum com esgoto e fertilizantes."},{"id":6881,"materia":"bio","nivel":3,"enunciado":"Pai do grupo A (IAi) e mãe do grupo B (IBi) podem ter filhos dos grupos:","opcoes":["A, B, AB e O","Só A e B, como os pais","Só AB, pela mistura","Só O"],"explicacao":"Cada um pode passar seu alelo dominante ou o i."},{"id":6882,"materia":"bio","nivel":4,"enunciado":"Mulher portadora de daltonismo e homem de visão normal. A chance de um filho homem ser daltônico é:","opcoes":["50%","25%","100%","0%"],"explicacao":"O filho recebe o X da mãe, que pode ser o afetado."},{"id":6883,"materia":"bio","nivel":3,"enunciado":"A diferença entre vacina e soro é que:","opcoes":["A vacina gera imunidade ativa; o soro, passiva","Os dois geram imunidade ativa e duradoura","O soro previne e a vacina trata a doença","Não há diferença"],"explicacao":"O soro traz anticorpos prontos."},{"id":6884,"materia":"bio","nivel":3,"enunciado":"A resistência de bactérias a antibióticos se explica por:","opcoes":["Seleção das bactérias que já eram resistentes","O antibiótico \"ensinar\" a bactéria a se defender","Contágio do remédio entre as pessoas","Fotossíntese das bactérias"],"explicacao":"O uso inadequado favorece as resistentes."},{"id":6885,"materia":"bio","nivel":3,"enunciado":"O bioma de árvores de troncos tortuosos e casca grossa, adaptado ao fogo, é o:","opcoes":["Cerrado","Pampa","Mata Atlântica","Amazônia"],"explicacao":"É a savana brasileira."},{"id":6886,"materia":"bio","nivel":4,"enunciado":"No ciclo do nitrogênio, as bactérias que transformam o N₂ do ar em amônia são as:","opcoes":["Fixadoras, como o Rhizobium","Desnitrificantes","Decompositoras de celulose","Fotossintetizantes do mar"],"explicacao":"Vivem em nódulos nas raízes de leguminosas."},{"id":6887,"materia":"bio","nivel":3,"enunciado":"A meiose produz células:","opcoes":["Com metade dos cromossomos, como os gametas","Idênticas à célula-mãe, como na mitose","Com o dobro de cromossomos da célula-mãe","Sem núcleo"],"explicacao":"A mitose produz células iguais."},{"id":6888,"materia":"bio","nivel":3,"enunciado":"No RNA, a base que substitui a timina do DNA é a:","opcoes":["Uracila","Adenina","Citosina","Guanina"],"explicacao":"No DNA: A-T e C-G."},{"id":6889,"materia":"his","nivel":3,"enunciado":"O Estado Novo (1937-1945) foi marcado por:","opcoes":["Ditadura de Vargas, censura e Constituição outorgada","Eleições livres e diretas para todos os cargos","Parlamentarismo e volta da monarquia","Fim da indústria nacional"],"explicacao":"O DIP controlava a imprensa."},{"id":6890,"materia":"his","nivel":3,"enunciado":"O Ato Institucional nº 5 (1968):","opcoes":["Permitiu fechar o Congresso e suspendeu o habeas corpus","Convocou eleições diretas para presidente","Aboliu definitivamente a censura à imprensa","Criou a Petrobras"],"explicacao":"Foi o ato mais duro da ditadura militar."},{"id":6891,"materia":"his","nivel":2,"enunciado":"O movimento Diretas Já (1984) pedia:","opcoes":["Eleição direta para presidente","A volta da monarquia","O fechamento do Congresso","A independência do Nordeste"],"explicacao":"A emenda Dante de Oliveira foi rejeitada."},{"id":6892,"materia":"his","nivel":2,"enunciado":"O Iluminismo defendia:","opcoes":["A razão e a crítica ao absolutismo","O poder divino dos reis absolutistas","A volta do feudalismo e da servidão","O fim da ciência"],"explicacao":"Inspirou as revoluções liberais."},{"id":6893,"materia":"his","nivel":4,"enunciado":"O Plano Marshall foi:","opcoes":["Ajuda econômica dos EUA para reconstruir a Europa","Plano s